import {createTDGraph,moveTDNode,tdWire} from './td-model.js';
export function mountTD(host,api){
 const say=(en,cn)=>document.documentElement.lang.startsWith('zh')?cn:en,t=s=>api.localize(s),projects=api.projects,byId=new Map(projects.map(p=>[p.id,p])),key='creativeos-td-project-graph-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}let graph=createTDGraph(projects,saved),selected=graph.nodes[0].id,scale=1,offset={x:0,y:0},drag=null,raf=0,pending=null,saveTimer=0;
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n},btn=(text,fn)=>{const n=el('button','',text);n.type='button';n.onclick=fn;return n},current=()=>graph.nodes.find(n=>n.id===selected),project=()=>byId.get(selected);
 host.className='td-workspace';const top=el('header','os-toolbar td-top'),path=el('span','td-path'),status=el('span','td-save-status'),reset=btn(say('Fit all','适应全部'),()=>fit()),open=btn('Full Project ↗',()=>api.openDetails(selected));top.append(el('strong','','TouchDesigner'),path,status,reset,open);
 const body=el('div','td-body'),left=el('aside','td-browser'),center=el('main','td-center'),right=el('aside','td-parameters');left.append(el('h3','',say('All projects','全部项目')));const projectButtons=new Map();for(const p of projects){const b=btn('▧ '+t(p.title),()=>{select(p.id);focusNode()});projectButtons.set(p.id,b);left.append(b)}left.append(el('small','td-note',say('Arrange your project network. Labels, notes, preview settings and connections are saved on this device.','自由编排作品网络。名称、备注、预览参数和连线保存在此设备。')));
 const strip=el('div','td-network-bar'),zoom=el('input');zoom.type='range';zoom.min='15';zoom.max='150';zoom.value='100';zoom.setAttribute('aria-label',say('Network zoom','节点画布缩放'));zoom.oninput=()=>{const old=scale;scale=Number(zoom.value)/100;offset={x:stage.clientWidth/2-(stage.clientWidth/2-offset.x)*scale/old,y:stage.clientHeight/2-(stage.clientHeight/2-offset.y)*scale/old};transform()};strip.append(el('span','','/portfolio'),el('span','',projects.length+' '+say('project nodes','个项目节点')),zoom);
 const stage=el('div','td-network'),world=el('div','td-world');stage.append(world);const ns='http://www.w3.org/2000/svg',wires=document.createElementNS(ns,'svg');wires.setAttribute('viewBox','0 0 1120 800');wires.classList.add('td-wires');world.append(wires);const nodes=new Map(),wireElements=new Map();
 for(const node of graph.nodes){const n=btn('',()=>select(node.id));n.className='td-node';n.dataset.nodeId=node.id;n.setAttribute('aria-label',t(byId.get(node.id).title));const im=el('img');im.alt='';im.loading='lazy';im.draggable=false;n.append(el('span','td-node-head','COMP / '+node.id),im,el('strong','',t(node.label)));n.ondblclick=()=>api.openImage(byId.get(node.id).images,node.image,byId.get(node.id).title);n.onkeydown=e=>{const d={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[e.key];if(d){e.preventDefault();Object.assign(node,moveTDNode(node,d[0]*scale,d[1]*scale,scale));drawNode(node);drawWires();save()}};world.append(n);nodes.set(node.id,n);drawNode(node)}
 const viewer=el('section','td-viewer'),bar=el('div','td-viewer-bar'),preview=btn('',()=>api.openImage(project().images,current().image,project().title)),previewImage=el('img');preview.className='td-preview';previewImage.alt='';preview.append(previewImage);bar.append(el('strong','','Output Viewer'),el('span','',say('Click to enlarge','点击放大')));const tray=el('div','td-tray');viewer.append(bar,preview,tray);center.append(strip,stage,viewer);body.append(left,center,right);const footer=el('footer','td-footer',say('Drag nodes to arrange · Drag background to pan · Arrow keys move focused node · Edit in Parameters','拖拽节点排列 · 拖动背景平移 · 方向键移动聚焦节点 · 右侧编辑参数'));host.append(top,body,footer);host.dispatchEvent(new host.ownerDocument.defaultView.Event('portfolio-toolbar-ready',{bubbles:true}));
 function save(){clearTimeout(saveTimer);saveTimer=0;try{localStorage.setItem(key,JSON.stringify(graph));status.textContent=say('Saved locally','已保存')}catch{status.textContent=say('Session only','仅本次有效')}}
 function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,250)}
 function drawNode(node){const n=nodes.get(node.id);if(!n)return;n.style.transform=`translate(${node.x}px,${node.y}px)`;const label=n.querySelector('strong'),text=t(node.label);if(label.textContent!==text)label.textContent=text;const im=byId.get(node.id).images[node.image],img=n.querySelector('img');if(im&&img.getAttribute('src')!==(im.small||im.thumb))img.src=im.small||im.thumb;const filter=`brightness(${node.brightness}%) saturate(${node.saturation}%)`;if(img.style.filter!==filter)img.style.filter=filter;n.setAttribute('aria-pressed',String(node.id===selected))}
 function drawWires(){const keep=new Set();for(const [from,to] of graph.edges){const key=from+':'+to;keep.add(key);let p=wireElements.get(key);if(!p){p=document.createElementNS(ns,'path');wireElements.set(key,p);wires.append(p)}const d=tdWire(graph.nodes.find(n=>n.id===from),graph.nodes.find(n=>n.id===to));if(p.getAttribute('d')!==d)p.setAttribute('d',d)}for(const [key,p] of wireElements)if(!keep.has(key)){p.remove();wireElements.delete(key)}}
 function transform(){world.style.transform=`translate(${offset.x}px,${offset.y}px) scale(${scale})`;zoom.value=String(scale*100)}
 function fit(){const minX=Math.min(...graph.nodes.map(n=>n.x)),minY=Math.min(...graph.nodes.map(n=>n.y)),width=Math.max(...graph.nodes.map(n=>n.x+148))-minX+50,height=Math.max(...graph.nodes.map(n=>n.y+110))-minY+40;scale=Math.max(.15,Math.min(stage.clientWidth/width,stage.clientHeight/height,.9));offset={x:(stage.clientWidth-width*scale)/2-minX*scale+20*scale,y:15-minY*scale};transform()}
 function focusNode(){const n=current();scale=Math.max(scale,.7);offset={x:stage.clientWidth/2-(n.x+74)*scale,y:stage.clientHeight/2-(n.y+50)*scale};transform()}
 function select(id){selected=id;for(const n of graph.nodes)nodes.get(n.id).setAttribute('aria-pressed',String(n.id===id));projectButtons.forEach((b,k)=>b.setAttribute('aria-pressed',String(k===id)));path.textContent='/portfolio/'+id;inspect();showPreview()}
 function showPreview(){const node=current(),p=project(),im=p.images[node.image];previewImage.src=im.preview||im.thumb;previewImage.alt=t(im.name);previewImage.style.filter=`brightness(${node.brightness}%) saturate(${node.saturation}%)`;tray.replaceChildren();p.images.forEach((im,i)=>{const b=btn('',()=>{node.image=i;drawNode(node);showPreview();save()});b.setAttribute('aria-label',t(im.name));b.setAttribute('aria-pressed',String(i===node.image));const img=el('img');img.src=im.small||im.thumb;img.alt='';img.loading='lazy';b.append(img);tray.append(b)})}
 function field(label,tag,value,change){const row=el('label','td-edit-field',label),input=el(tag);input.value=value;input.oninput=()=>change(input.value);row.append(input);right.append(row);return input}
 function inspect(){const node=current(),p=project();right.scrollTop=0;right.replaceChildren(el('h3','',t(p.title)),el('div','td-family','COMP / '+say('Parameters','参数')));const label=field(say('Node label','节点名称'),'input',node.label,v=>{node.label=v;drawNode(node);scheduleSave()});label.maxLength=80;const note=field(say('Notes','备注'),'textarea',node.note,v=>{node.note=v;scheduleSave()});note.maxLength=1500;
 for(const [name,prop,min,max] of [[say('Brightness','亮度'),'brightness',40,160],[say('Saturation','饱和度'),'saturation',0,160]]){const row=el('label','td-param-slider',name),input=el('input');input.type='range';input.min=min;input.max=max;input.value=node[prop];input.oninput=()=>{node[prop]=Number(input.value);drawNode(node);previewImage.style.filter=`brightness(${node.brightness}%) saturate(${node.saturation}%)`;scheduleSave()};row.append(input);right.append(row)}
 const labelRow=el('label','td-edit-field',say('Connect to','连接到')),target=el('select');for(const other of graph.nodes.filter(n=>n.id!==selected)){const option=el('option','',t(byId.get(other.id).title));option.value=other.id;target.append(option)}labelRow.append(target);right.append(labelRow,btn(say('Add connection','添加连线'),()=>{if(!graph.edges.some(([a,b])=>a===selected&&b===target.value)){graph.edges.push([selected,target.value]);drawWires();save()}}),btn(say('Remove node connections','移除此节点连线'),()=>{graph.edges=graph.edges.filter(([a,b])=>a!==selected&&b!==selected);drawWires();save()}),btn(say('Reset this node','复位此节点'),()=>{const fresh=createTDGraph(projects).nodes.find(n=>n.id===selected);Object.assign(node,fresh);drawNode(node);drawWires();select(selected);save()}),el('p','td-note',say('Edits affect your local workspace only. Original portfolio content is preserved.','编辑仅影响本地工作台，原始作品内容保持不变。')),btn('Full Project ↗',()=>api.openDetails(selected)))}
 function applyMove(){raf=0;if(!drag||!pending)return;const point=pending;pending=null;if(drag.node){Object.assign(drag.node,moveTDNode(drag.start,point.x-drag.x,point.y-drag.y,scale));drawNode(drag.node);drawWires()}else{offset={x:drag.ox+point.x-drag.x,y:drag.oy+point.y-drag.y};transform()}}
 stage.onpointerdown=e=>{if(e.button!==0)return;const n=e.target.closest('[data-node-id]');if(!n&&e.target.closest('button,input'))return;if(n){select(n.dataset.nodeId);n.classList.add('td-node-moving')}drag={x:e.clientX,y:e.clientY,ox:offset.x,oy:offset.y,node:n?current():null,start:n?{x:current().x,y:current().y}:null};stage.setPointerCapture(e.pointerId);e.preventDefault()};stage.onpointermove=e=>{if(!drag)return;pending={x:e.clientX,y:e.clientY};if(!raf)raf=requestAnimationFrame(applyMove)};const end=()=>{if(!drag)return;if(raf)cancelAnimationFrame(raf);applyMove();if(drag.node){nodes.get(drag.node.id).classList.remove('td-node-moving');save()}drag=null};stage.onpointerup=stage.onpointercancel=stage.onlostpointercapture=end;
 drawWires();select(selected);const resize=new ResizeObserver(()=>fit());resize.observe(stage);fit();return()=>{if(raf)cancelAnimationFrame(raf);if(saveTimer)save();resize.disconnect();drag=null;host.replaceChildren()};
}
